INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", 0, 1.4, "お！\nあそこに困ってそうな人発見！", 1001, 0, "春咲 ひより", 0, 1, 0, 1, 1, "ねぇねぇ、騎士クン\n手伝ってあげようよ～", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "みんなみたいに\nわたしも強くならなきゃ", 0, 1.4, "大切な人を\n守れるようになりたい…って", 1002, 0, "草野 優衣", 0, 1, 0, 1, 1, "わ、わたし、\nなに言ってるんだろ\nあはは…", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "フェンシングを始めてみては？", 0, 1.4, "キミに必要な集中力と感性が", 1003, 0, "士条 怜", 0, 1, 0, 1, 1, "少しは磨かれると思いますよ。", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "ねぇ、にいちゃん！", 0, 1.5, "今日はなにして遊ぶ？", 1004, 0, "穂高 みそぎ", 0, 1, 0, 1, 1, "みそぎはねぇ、\nかくれんぼやりたい！", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "風宮あかりです", 0, 1.4, "ねぇ…", 1006, 0, "風宮 あかり", 0, 1, 0, 1, 1, "私といっしょに…\nいかない？", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "出雲宮子なのー", 0, 1.5, "プリンたべたいのー", 1007, 0, "出雲 宮子", 0, 1, 0, 1, 1, "食べ物の恨みは怖いのー", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "ボクは虹村雪。", 0, 1.4, "キミもボクの美貌に\n吸い寄せられたんだね。", 1008, 0, "虹村 雪", 0, 1, 0, 1, 1, "いいよ。\n見られることは運命さ…", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "フッ…聞いて後悔するがいい！", 0, 1.4, "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", 1009, 0, "柊杏奈", 0, 1, 0, 1, 1, "人呼んで「疾風の冥姫」!!", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "マホマホ王国のプリンセス、\nまほ姫どす", 0, 1.5, "うさぎさん、\n運命の王子はんに巡りあわせてくれて", 1010, 0, "姫宮 真歩", 0, 1, 0, 1, 1, "ほんまおおきにやわ～♪", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "衣之咲璃乃です！", 0, 1.4, "生き別れたお兄ちゃんを探して\n三千世界！", 1011, 0, "衣之咲 璃乃", 0, 1, 0, 1, 1, "ここで会ったが\n100年目～！", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "私はハツネ、\n結構強いんだよ。\nきらーん☆", 0, 1.4, "ち、超能力って…\n何のことかな～？", 1012, 0, "柏崎 初音", 0, 1, 0, 1, 1, "…って、お願い！\n誰にも言わないでおいて～！", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "ちょす！\n美波鈴奈だよ～♪", 0, 1.4, "一応カリスマ読モJKやってまっす！", 1016, 0, "美波 鈴奈", 0, 1, 0, 1, 1, "ヒデサイまぢ\nGF（グッドフィーリング）～♪", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "はいたーい。\n喜屋武香織さー。", 0, 1.4, "東京は遊園地みたいなところさー", 1017, 0, "喜屋武 香織", 0, 1, 0, 1, 1, "でも、沖縄もとってもいいとこさー", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "支倉伊緒です。", 0, 1.4, "先生って呼ばれるのは\nくすぐったいから", 1018, 0, "支倉 伊緒", 0, 1, 0, 1, 1, "イオちゃんって呼んでね。", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", 0, 1.5, "あ！/\お兄ちゃ～ん\nまってよ～", 1020, 0, "茜 ミミ", 0, 1, 0, 1, 1, "ミミをおいてかないでぇ～", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "あ…あの…えっと…\n栗…林…くるみ…です……", 0, 1.5, "あの……\nふぇ……", 1021, 0, "栗林 くるみ", 0, 1, 0, 1, 1, "ふぇぇぇぇぇん……", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "風宮よりです。\nあああああ！", 0, 1.4, "こんな私に貴重な時間を\n割いていただき、", 1022, 0, "風宮 より", 0, 1, 0, 1, 1, "なんてありがとうございます！", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "私、アヤネ！\nぷうきちと一緒についてってあげるね！", 0, 1.5, "おにいちゃんどこいくの？\nえ？", 1023, 0, "北条 綾音", 0, 1, 0, 1, 1, "私こっち行きたいー\nね、早く早くー", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "わっ…わっ…私、\n天野すずめといいます！", 0, 1.4, "ふ、不束者ですが\nどうぞ末永く…って、", 1025, 0, "天野 すずめ", 0, 1, 0, 1, 1, "これて何か違う…\nあああすみません！", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "……クスクス…私は\n…倉石恵理子……", 0, 1.4, "あなたは…運命の……\n伴侶……", 1027, 0, "倉石 恵理子", 0, 1, 0, 1, 1, "離しませんわ………\n絶対に…!!", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", 0, 1.4, "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", 1028, 0, "佐々木 咲恋", 0, 1, 0, 1, 1, "…そうでしょ？？", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "桜井望だよ！\nよろしくねっ", 0, 1.4, "ぇっと…\nキミ、私のこと知らないの?!", 1029, 0, "桜井 望", 0, 1, 0, 1, 1, "あはは、\n私もまだまだだなぁ～", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "デケデケデンっ！", 0, 1.4, "初めまして、\n私はニノン・ジュベール申すデス！", 1030, 0, "ニノン・ジュベール", 0, 1, 0, 1, 1, "ショーグン、\nワタシと一緒に天下統一デース！", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "上喜しのぶです。\n手元のドクロが父です。", 0, 1.4, "でもって私の隣にいるのが……\nえ、見えない？", 1031, 0, "上喜 しのぶ", 0, 1, 0, 1, 1, "おかしいですね……", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "目指すはビッグな\nお笑い芸人だっぺ！", 0, 1.5, "けんども\nそれには足りないモンが…", 1033, 0, "野戸まひる", 0, 1, 0, 1, 1, "そう、\nオラのボケに突っ込める相方が…！", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", 0, 1.4, "ちょっと緊張しちゃって…", 1034, 0, "綾瀬 ゆかり", 0, 1, 0, 1, 1, "ちょ\nちょっと一杯飲んできます…！", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "氷川鏡華…です", 0, 1.5, "知らない人とは話しちゃいけないので", 1036, 0, "氷川 鏡華", 0, 1, 0, 1, 1, "これ以上お話しすることは…\nないです！", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "柏崎…栞です。", 0, 1.4, "……あ、アラーム。", 1038, 0, "柏崎 栞", 0, 1, 0, 1, 1, "私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "ふ、双葉碧です。", 0, 1.4, "私、一人も友達がいなくて……", 1040, 0, "双葉 碧", 0, 1, 0, 1, 1, "野に咲く花が、\n唯一の話相手です。", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "三角千歌です。", 0, 1.4, "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", 1042, 0, "三角 千歌", 0, 1, 0, 1, 1, "そう思っています。", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "安芸真琴だ。", 0, 1.4, "あぁ？\nお前のそいつの仲間か？", 1043, 0, "安芸 真琴", 0, 1, 0, 1, 1, "う、疑ってすまなかったな…", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "わらわこそは夜を総べる者！", 0, 1.4, "生けとし生ける全ての者よ！", 1044, 0, "イリヤ・オーンスタイン", 0, 1, 0, 1, 1, "わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "そこで騎士は妖精を乱暴に……", 0, 1.4, "ぐふふふふ……はっ！", 1045, 0, "遠見 空花", 0, 1, 0, 1, 1, "ｌク、クウカに何かご用ですか!?", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "宮坂たまきにゃ♪\n猫はいいにゃよ？", 0, 1.4, "自由気ままで♪\n寝て遊んで、食べてケンカして…", 1046, 0, "宮坂たまき", 0, 1, 0, 1, 1, "う～ん…\n猫ってホントに最高にゃ～♪", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "大神美冬よ！", 0, 1.4, "それでは早速クエストに…", 1048, 0, "大神 美冬", 0, 1, 0, 1, 1, "…と思ったら\nバイトの時間だ！\nまたあとでね！", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "星野静流だよ！", 0, 1.4, "クエストもバトルも\n掃除も洗濯も", 1049, 0, "星野静流", 0, 1, 0, 1, 1, "お姉ちゃんがぜ～んぶ\nやってあげるからね！", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "アタシは玉泉美咲。", 0, 1.5, "見ての通りの\nセクシー美少女で", 1050, 0, "玉泉美咲", 0, 1, 0, 1, 1, "学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "？？？", 0, 1.4, "？？？？", 1052, 0, "リマ", 0, 1, 0, 1, 1, "？？？？", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "モニカ・ヴァイスヴィントだ。", 0, 1.5, "菓子でつろうなどと\n稚拙な策を……", 1053, 0, "モニカ・ヴァイスヴィント", 0, 1, 0, 1, 1, "そ、そこまでいうなら\nもらってやる", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "モニカ・ヴァイスヴィントだ。", 0, 1.5, "菓子でつろうなどと\n稚拙な策を……", 1058, 0, "ペコリーヌ", 0, 1, 0, 1, 1, "そ、そこまでいうなら\nもらってやる", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "モニカ・ヴァイスヴィントだ。", 0, 1.5, "菓子でつろうなどと\n稚拙な策を……", 1059, 0, "コッコロ", 0, 1, 0, 1, 1, "そ、そこまでいうなら\nもらってやる", 2);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (0, "モニカ・ヴァイスヴィントだ。", 0, 1.5, "菓子でつろうなどと\n稚拙な策を……", 1060, 0, "キャル", 0, 1, 0, 1, 1, "そ、そこまでいうなら\nもらってやる", 2);
